/**
 * The materials a planet's plugins go on, as they join the scene: those there
 * now, then each one added, each handed over once. The scene's count of
 * materials alone misses one that comes as another goes between two looks; it
 * draws without its plugins and takes them later, and a plugin added to a
 * material that has drawn makes the engine throw away its draw state. So the
 * scene is looked over again whenever its count has changed or a material has
 * gone since the last look: any arrival does one or the other. (The scene's
 * own notice of an added material comes later, after a frame may have drawn
 * it; its notice of a removed one comes at once.)
 */
import type { Scene } from '@babylonjs/core/scene';

type SceneMaterial = Scene['materials'][number];

export interface MaterialArrivals {
  /**
   * Hands each material come since the last call, and still in the scene, to `fn`; one that `fn` declines for now
   * (it returns false: a planet's that holds no one yet) is handed over again at every later call until taken.
   */
  take(fn: (m: SceneMaterial) => unknown): void;
  dispose(): void;
}

export function materialArrivals(scene: Scene): MaterialArrivals {
  const seen = new WeakSet<SceneMaterial>();
  // Declined for now, to be offered again.
  const later = new Set<SceneMaterial>();
  let looked = -1;
  let live = true;
  let gone = false;
  const removed = scene.onMaterialRemovedObservable.add(() => {
    gone = true;
  });
  return {
    take(fn) {
      if (!live) return;
      for (const m of [...later]) {
        if (!scene.materials.includes(m)) later.delete(m);
        else if (fn(m) !== false) later.delete(m);
      }
      if (scene.materials.length === looked && !gone) return;
      looked = scene.materials.length;
      gone = false;
      for (const m of [...scene.materials]) {
        if (seen.has(m)) continue;
        seen.add(m);
        if (fn(m) === false) later.add(m);
      }
    },
    dispose() {
      scene.onMaterialRemovedObservable.remove(removed);
      live = false;
    },
  };
}
